sys_ui_action.script:
if (!gs.hasRole('x_travel_buddy_app.Admin') && current.assigned_to != gs.getUserID()) {
    gs.addErrorMessage('Only the assigned Buddy or an Admin can reject this trip request.');
    current.setAbortAction(true);
} else if (current.state != 1) {
    gs.addErrorMessage('Only trip requests in Pending Approval can be rejected.');
    current.setAbortAction(true);
} else {
    current.state = 5;
    current.update();

    try {
        var travelerId = current.getValue('u_traveler');
        if (travelerId) {
            var travelerGr = new GlideRecord('sys_user');
            if (travelerGr.get(travelerId)) {
                var toAddr = travelerGr.getValue('email');
                if (toAddr) {
                    var emailGr = new GlideRecord('sys_email');
                    emailGr.initialize();
                    emailGr.type = 'send-ready';
                    emailGr.state = 'ready';
                    emailGr.recipients = toAddr;
                    emailGr.content_type = 'text/plain';
                    emailGr.subject = 'Travel Buddy: Your trip request was declined - ' + current.getDisplayValue('number');
                    emailGr.body = 'Hi ' + travelerGr.getDisplayValue('first_name') + ',\n\n' +
                        'Your trip request ' + current.getDisplayValue('number') + ' was declined by your buddy.\n' +
                        'Please choose a different buddy or different dates.\n\n' +
                        '- Travel Buddy App';
                    emailGr.insert();
                }
            }
        }
    } catch (e) {
        gs.error('TBA reject notification failed: ' + e.message);
    }

    gs.addInfoMessage('Trip request rejected.');
    action.setRedirectURL(current);
}
